/* Python Pathways: exercise ladders (Exercise 1 to 10 in every lesson, getting harder step by step).
   AUTO-BUILT from the dev sources. Loaded after the first script in index.html and uses its helpers (R, py, c, pre, fnCheck, ...). */
/* ===== Exercise ladders: every lesson has Exercise 1 → 10, each a little harder than the last, on the same topic.
   Every student gets their own random version of each exercise (different numbers, words and names).
   Uses the helpers defined above (R, py, c, pre, esc, fnCheck, lines, uses, ST, FN, WORDS, NAMES, PHRASES, LV, sum, T, D). */
const L_STAGES = [["Warm-up", 1], ["Warm-up", 1], ["Build", 2], ["Build", 2], ["Apply", 3], ["Apply", 3], ["Stretch", 4], ["Stretch", 4], ["Challenge", 5], ["Challenge", 5]];
const J = s => JSON.stringify(s);
const chk = (...parts) => parts.filter(Boolean).join("\n");
const noSp = (t, m) => "if " + J(t.replace(/ /g, "")) + " not in code.replace(\" \", \"\"): fail(" + J(m) + ")";
const noQuote = (v, m) => "if " + J('"' + v + '"') + " in code or " + J("'" + v + "'") + " in code: fail(" + J(m) + ")";
const banned = (t, m) => "if " + J(t) + " in code: fail(" + J(m) + ")";
const ins = (cases) => cases.map(([i, out]) => ({in: i.map(String), check: lines(out)}));
const PETS = ["cat", "dog", "parrot", "rabbit", "hamster", "goldfish", "tortoise", "puppy"];
const FOODS = ["pizza", "mango", "pasta", "sushi", "tacos", "noodles", "pancakes", "falafel"];
const COLOURS = ["red", "blue", "green", "purple", "orange", "yellow", "pink", "silver"];
const CITIES = ["Dubai", "Paris", "Tokyo", "Cairo", "Lagos", "Sydney", "Toronto", "Mumbai"];
const SUBJ = ["Maths", "Science", "English", "Art", "Music", "History", "Coding", "French"];
const LW = () => WORDS.filter(w => /^[a-z]+$/.test(w));
const pickW = () => R.pick(LW());
const sampW = k => R.sample(LW(), k);
const uniq = a => [...new Set(a)];
const rnd = (x, d) => { const f = Math.pow(10, d); return Math.round(x * f) / f; };
const pyRound = (x, d) => { const f = Math.pow(10, d || 0); const y = x * f; const r = Math.round(y); return (Math.abs(y % 1) === 0.5 ? (r % 2 === 0 ? r : r - 1) : r) / f; };
const words = s => s.split(/\s+/).filter(Boolean);
const capW = w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
const DIGITS = n => String(n).split("").map(Number);
const numArg = (n, m) => "import re\nif not re.search(" + J(",\\s*" + String(n).replace(".", "\\.") + "\\s*[,)]") + ", code): fail(" + J(m) + ")";
const fstr = "if 'f\"' not in code and \"f'\" not in code: fail(\"Use an f-string: put the letter f just before the opening quote.\")";
const reNeed = (rx, m) => "import re\nif not re.search(" + J(rx) + ", code): fail(" + J(m) + ")";
const oneOf = (opts, m) => "if not any(x in code.replace(\" \", \"\") for x in " + py(opts.map(o => o.replace(/ /g, ""))) + "): fail(" + J(m) + ")";
const pyCall = (name, argsPy, expPy, label) => "eq(" + name + "(" + argsPy + "), " + expPy + ", " + J(label || name + "(" + argsPy + ")") + ")";

// ---- helpers from lad_6_dp_advanced.js
const NODE_SRC = "class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n";
const BST_NODE = "class Node:\n    def __init__(self, value):\n        self.value = value\n        self.left = None\n        self.right = None\n";
const BST_INSERT = "\n    def insert(self, value):\n        if self.root is None:\n            self.root = Node(value)\n            return\n        cur = self.root\n        while True:\n            if value < cur.value:\n                if cur.left is None:\n                    cur.left = Node(value)\n                    return\n                cur = cur.left\n            else:\n                if cur.right is None:\n                    cur.right = Node(value)\n                    return\n                cur = cur.right\n";
const BST_BASE = BST_NODE + "\nclass BST:\n    def __init__(self):\n        self.root = None\n" + BST_INSERT;
const LL_BASE = NODE_SRC + "\nclass LinkedList:\n    def __init__(self, values=()):\n        self.head = None\n        for v in reversed(values):\n            node = Node(v)\n            node.next = self.head\n            self.head = node\n\n    def to_list(self):\n        out, cur = [], self.head\n        while cur:\n            out.append(cur.data)\n            cur = cur.next\n        return out\n";
const bstBuild = vals => { const root = {v: vals[0], l: null, r: null}; vals.slice(1).forEach(x => { let c_ = root; while (true){ if (x < c_.v){ if (!c_.l){ c_.l = {v: x, l: null, r: null}; break; } c_ = c_.l; } else { if (!c_.r){ c_.r = {v: x, l: null, r: null}; break; } c_ = c_.r; } } }); return root; };
const bstOrder = (n, kind) => { const out = []; const w = t => { if (!t) return; if (kind === "pre") out.push(t.v); w(t.l); if (kind === "in") out.push(t.v); w(t.r); if (kind === "post") out.push(t.v); }; w(n); return out; };
const bstVals = () => uniq(R.list(8, 1, 99));

